mapper.sql:
	FROM product a
	LEFT JOIN member b on a.member_memberSeq = b.memberSeq
 	LEFT JOIN pdReview c on a.pdSeq = c.member_memberSeq
	WHERE 1=1
	 AND a.pdUseNy= #{shUseNy}
	 AND a.pdDelNy = #{shDelNy}

		AND a.regDateTime BETWEEN #{shDateStart} AND
			#{shDateEnd}

		AND a.modDateTime BETWEEN #{shDateStart} AND
			#{shDateEnd}

mapper.insert:
INSERT INTO product (
pdName
,pdUseNy
,pdOrder
,pdDesc
,pdDelNy
,pdPrice
,pdPriceDcRate
,pdFavorite
,pdMedia
,pdTerm
,pdReview
,pdRating
,regDateTime
,modDateTime
,member_memberSeq
) VALUES (
#{pdName}
,#{pdUseNy}
,#{pdOrder}
,#{pdDesc}
,#{pdDelNy}
,#{pdPrice}
,#{pdPriceDcRate}
,#{pdFavorite}
,#{pdMedia}
,#{pdTerm}
,#{pdReview}
,#{pdRating}
,now()
,now()
,#{memberMemberSeq}
)

	SELECT last_insert_id()

mapper.update:
UPDATE product
SET
pdName = #{pdName}
,pdUseNy =
#{pdUseNy}
,pdOrder = #{pdOrder}
WHERE 1=1
AND pdSeq
= #{pdSeq}
